const $=s=>document.querySelector(s);const config=window.SPA_ASSETS;
function startIntro(){if(!document.documentElement.classList.contains('intro-pending'))return;document.documentElement.classList.remove('intro-pending');document.documentElement.classList.add('intro-ready')}setTimeout(startIntro,2500);
document.querySelectorAll('[data-asset]').forEach(box=>{const a=config[box.dataset.asset];if(!a)return;if(a.src){const img=document.createElement('img');img.src=a.src;img.alt=a.alt||'';if(a.mobile){const pic=document.createElement('picture'),source=document.createElement('source');source.media='(max-width: 700px)';source.srcset=a.mobile;pic.append(source,img);box.prepend(pic)}else box.prepend(img);img.onerror=()=>img.remove()}if(a.video&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const v=document.createElement('video');v.src=a.video;v.muted=true;v.autoplay=true;v.playsInline=true;v.preload='metadata';v.setAttribute('aria-hidden','true');v.addEventListener('playing',()=>{v.classList.add('is-playing');if(box.dataset.asset==='hero')startIntro()});v.addEventListener('error',()=>v.remove());if(box.dataset.asset==='hero')enableReverseCycle(v);else v.loop=true;box.append(v)}});
// Play forward, then seek backward in small steps before playing forward again.
function enableReverseCycle(video){let reversing=false,lastFrame=0,frame=0;function reverse(now){if(!reversing)return;if(document.hidden){lastFrame=now;frame=requestAnimationFrame(reverse);return}if(!lastFrame)lastFrame=now;if(now-lastFrame>=42&&!video.seeking){const elapsed=Math.min((now-lastFrame)/1000,.15);lastFrame=now;const next=Math.max(0,video.currentTime-elapsed);video.currentTime=next;if(next===0){reversing=false;video.addEventListener('seeked',()=>video.play().catch(()=>{}),{once:true});return}}frame=requestAnimationFrame(reverse)}video.addEventListener('ended',()=>{reversing=true;lastFrame=0;frame=requestAnimationFrame(reverse)});video.addEventListener('error',()=>{reversing=false;cancelAnimationFrame(frame)})}
const services={single:{name:'Single Room Massage',min:1,max:1,duration:60,price:800},couples:{name:'Couples Suite',min:2,max:2,duration:60,price:1800},family:{name:'Barkada / Family Spa Lounge',min:1,max:6,duration:90,price:4000}};const money=n=>'₱'+n.toLocaleString('en-PH');const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const time=m=>{let h=Math.floor(m/60),suffix=h>=12?'PM':'AM';return `${h%12||12}:${String(m%60).padStart(2,'0')} ${suffix}`};
$('#date').min=today();$('#date').value=today();function clearResult(){$('#result').textContent=''}function times(){let s=services[$('#service').value],select=$('#time');select.replaceChildren();let now=new Date(),parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Manila',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(now).split(':'),current=+parts[0]*60+(+parts[1]);for(let m=780;m+s.duration+30<=1260;m+=s.duration+30){if($('#date').value===today()&&m<=current)continue;select.add(new Option(`${time(m)} – ${time(m+s.duration)}`,m))}if(!select.options.length)select.add(new Option('Choose a later date',''));clearResult()}function estimate(){let s=services[$('#service').value],n=+$('#guests').value,extra=$('#service').value==='family'?Math.max(0,n-4)*750:0;$('#price').textContent=money(s.price+extra);$('#details').textContent=`${n} ${n===1?'guest':'guests'} · ${s.duration} minutes${$('#service').value==='family'?' · '+money(s.price)+' base'+(extra?' + '+money(extra)+' for additional guests':' (up to 4 guests)'):''}`;clearResult()}function updatePlannerImage(key){const box=$('.planner-art'),a=config[key],img=box.querySelector('img');if(!img||!a)return;img.alt=a.alt||'';img.hidden=false;img.onerror=()=>{img.hidden=true};img.src=a.src||''}function update(){let key=$('#service').value;let s=services[key];updatePlannerImage(key);$('#pricing-note').hidden=key!=='family';$('#guests').replaceChildren();for(let n=s.min;n<=s.max;n++)$('#guests').add(new Option(`${n} ${n===1?'guest':'guests'}`,n));if($('#service').value==='family')$('#guests').value=4;times();estimate()}$('#service').addEventListener('change',update);$('#guests').addEventListener('change',estimate);$('#date').addEventListener('change',times);$('#time').addEventListener('change',clearResult);document.querySelectorAll('[data-select]').forEach(a=>a.addEventListener('click',()=>{$('#service').value=a.dataset.select;update()}));$('#planner-form').addEventListener('submit',e=>{e.preventDefault();if(!$('#time').value)return;let s=services[$('#service').value];$('#result').textContent=`Your preview: ${s.name}, ${$('#guests').value} guest(s), ${$('#date').value}, ${$('#time').selectedOptions[0].text}. Estimated total ${$('#price').textContent}. This is not a reservation; availability has not been checked.`});update();
let timer=null,phase=0;$('#breath-toggle').addEventListener('click',()=>{if(timer){clearInterval(timer);timer=null;$('.breath').classList.remove('active');$('#breath-toggle').textContent='Begin breathing';$('#breath-word').textContent='';return}phase=0;$('.breath').classList.add('active');$('#breath-toggle').textContent='End breathing';$('#breath-word').textContent='Breathe in';timer=setInterval(()=>{phase=1-phase;$('#breath-word').textContent=phase?'Breathe out':'Breathe in'},4000)});if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e))}else document.querySelectorAll('.reveal').forEach(e=>e.classList.add('visible'));

// Keep the navigation visible and highlight the section currently in view.
const header=$('.header'),navLinks=[...document.querySelectorAll('.header nav a')];function updateNavigation(){header.classList.toggle('scrolled',window.scrollY>80);let active='';for(const id of ['experiences','about','visit']){const section=document.getElementById(id),r=section.getBoundingClientRect();if(r.top<=180&&r.bottom>180)active=id}navLinks.forEach(link=>{const current=link.getAttribute('href')==='#'+active;link.classList.toggle('active',current);if(current)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')})}window.addEventListener('scroll',updateNavigation,{passive:true});updateNavigation();
